     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { isBlankRichText, parseRichText } from 'app/utils/richText';
     4	
     5	const ZIMM_PRODUCT_MODEL_INFO_RECIPE = 'ZimmProductModelInfo';
     6	
     7	type ZimmProductModelInfoProps = {
     8	  /**
     9	   * Model copy from the product's `c_modelFit` attribute. Business Manager authors this as
    10	   * rich text, so it is parsed rather than rendered as a raw string.
    11	   */
    12	  modelInfo?: string;
    13	};
    14	
    15	/**
    16	 * Atom — the model line ("Model is 178cm and wears a size 0"). Renders nothing when
    17	 * `c_modelFit` is absent, which is the common case today.
    18	 *
    19	 * All styling, type included, lives in `zimmProductModelInfo.css.ts` and is consumed through the
    20	 * theme, per the one-canonical-styling-surface rule — the element carries no style prop of its
    21	 * own, so the recipe cannot be out-ranked by one.
    22	 *
    23	 * A `div`, not a `p`: `parseRichText` can return block-level nodes, and a `<p>` inside a `<p>`
    24	 * is invalid nesting that the browser silently repairs by splitting the element.
    25	 */
    26	export const ZimmProductModelInfo = ({ modelInfo }: ZimmProductModelInfoProps) => {
    27	  // Guard below the hook, never above it — an early return before `useStyleConfig` makes the
    28	  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error.
    29	  const styles = useStyleConfig(ZIMM_PRODUCT_MODEL_INFO_RECIPE, {});
    30	  if (isBlankRichText(modelInfo)) return null;
    31	  const content = parseRichText(modelInfo);
    32	
    33	  return (
    34	    <chakra.div __css={styles} data-testid="product-model-info">
    35	      {content}
    36	    </chakra.div>
    37	  );
    38	};

