import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useContentfulClient } from 'app/hooks/useContentfulClient';
import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry, RegionEntry } from 'app/types/contentful';
import FooterContainer, { scopeToRegion } from './index';

// See footerNavColumn/index.test.tsx's identical mock for why: ZimmIcon pulls in the base SFCC
// icons barrel, which throws under Vitest (SVG imports resolve to raw path strings here).
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

vi.mock('app/hooks/useContentfulClient', () => ({
  useContentfulClient: vi.fn(),
}));

// FooterContainer no longer calls useUiCopy() itself (BottomBar/ZimmSubscribeSection source
// their own microcopy directly — see their own test files). With no UiCopyProvider mounted in
// this render tree, useUiCopy() gracefully degrades to fallback-only text on its own, so no
// mock is needed here for that to behave correctly.

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseContentfulClient = vi.mocked(useContentfulClient);

// ---------------------------------------------------------------------------
// Fixture builders
// ---------------------------------------------------------------------------

const makeRegion = (siteId: string): RegionEntry => ({
  sys: { id: `region-${siteId}`, contentType: { sys: { id: 'region' } } },
  fields: { siteId, label: siteId },
});

const makeLink = (id: string, label: string, regions?: RegionEntry[]): LinkEntry => ({
  sys: { id, contentType: { sys: { id: 'link' } } },
  fields: { label, href: '#', regions },
});

const makeGroup = (id: string, links: LinkEntry[]): FooterNavGroupEntry => ({
  sys: { id, contentType: { sys: { id: 'footerNavGroup' } } },
  fields: { heading: id, links },
});

const makeConfig = (id: string, overrides: Partial<FooterConfigEntry['fields']> = {}): FooterConfigEntry => ({
  sys: { id, contentType: { sys: { id: 'footerConfig' } } },
  fields: {
    internalTitle: id,
    navGroups: [makeGroup('group-about', [makeLink('link-1', 'Our Story')])],
    ...overrides,
  },
});

// ---------------------------------------------------------------------------
// scopeToRegion — pure logic
// ---------------------------------------------------------------------------

describe('scopeToRegion', () => {
  const auOnly = makeRegion('ZimmermannAU');
  const auLink = makeLink('link-au', 'Book an Appointment', [auOnly]);
  const globalLink = makeLink('link-global', 'Our Story');

  test('drops a region-scoped link that does not match the current site', () => {
    const config = makeConfig('cfg', { navGroups: [makeGroup('group', [auLink, globalLink])] });

    const result = scopeToRegion(config, 'ZimmermannUS');

    expect(result.fields.navGroups[0].fields.links.map((l) => l.sys.id)).toEqual(['link-global']);
  });

  test('keeps a region-scoped link that matches the current site', () => {
    const config = makeConfig('cfg', { navGroups: [makeGroup('group', [auLink, globalLink])] });

    const result = scopeToRegion(config, 'ZimmermannAU');

    expect(result.fields.navGroups[0].fields.links.map((l) => l.sys.id)).toEqual(['link-au', 'link-global']);
  });

  test('applies the same scoping to legalLinks', () => {
    const config = makeConfig('cfg', { legalLinks: [auLink, globalLink] });

    const result = scopeToRegion(config, 'ZimmermannUS');

    expect(result.fields.legalLinks?.map((l) => l.sys.id)).toEqual(['link-global']);
  });

  test('handles legalLinks being undefined without throwing', () => {
    const config = makeConfig('cfg');

    expect(() => scopeToRegion(config, 'ZimmermannAU')).not.toThrow();
    expect(scopeToRegion(config, 'ZimmermannAU').fields.legalLinks).toBeUndefined();
  });

  test('preserves non-link fields on each nav group unchanged', () => {
    const group = makeGroup('group-contact', [globalLink]);
    group.fields.showContactChannels = true;
    const config = makeConfig('cfg', { navGroups: [group] });

    const result = scopeToRegion(config, 'ZimmermannAU');

    expect(result.fields.navGroups[0].fields.heading).toBe('group-contact');
    expect(result.fields.navGroups[0].fields.showContactChannels).toBe(true);
  });
});

// ---------------------------------------------------------------------------
// FooterContainer — Contentful fetch/resolve integration
// ---------------------------------------------------------------------------

function mockSite(id: string) {
  mockUseMultiSite.mockReturnValue({
    site: { id },
    buildUrl: (path: string) => path,
  });
}

function mockClient(getEntries: ReturnType<typeof vi.fn>) {
  mockUseContentfulClient.mockReturnValue({
    client: { getEntries } as never,
    previewUnavailable: false,
    isPreview: false,
  });
}

function renderContainer() {
  return render(
    <MemoryRouter>
      <FooterContainer />
    </MemoryRouter>,
  );
}

describe('FooterContainer', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockSite('ZimmermannAU');
  });

  test('renders nothing while the fetch is pending', async () => {
    let resolveFetch: (value: { items: FooterConfigEntry[] }) => void = () => {};
    const pending = new Promise<{ items: FooterConfigEntry[] }>((resolve) => {
      resolveFetch = resolve;
    });
    mockClient(vi.fn().mockReturnValue(pending));

